# Generated by Claudian.
"""Confirmation gate for irreversible actions.

WHY
---
Three skills — shut down, restart, empty trash — executed immediately on a
single transcription. Speech recognition is probabilistic, the conversation
window accepts commands with no wake word, and barge-in listens while the
speakers are playing. Any of those can surface a phrase the user never said.
"Shut down the Mac" from a podcast playing nearby should not end the session.

`shutdown_system.py` even carried a docstring promising this: "A future
improvement will add a confirmation step — until then the regex is
intentionally strict." The regex was the only thing standing between a
mishearing and a shutdown.

DESIGN
------
Borrowed from the behaviour OpenAI reported for GPT-6 Astra, which scored 0%
on going beyond its authorised scope versus 48.2% for the prior model, and
never circumvented its auto-review gate even when that gate was deliberately
made evadable. The lesson generalises: capable systems need a boundary they
cannot talk themselves past, and the boundary belongs outside the component
being gated.

So the gate lives here, not inside the skills. A skill declares that it needs
confirmation and hands over a callable; it cannot approve itself.

Deliberately narrow: only irreversible actions are gated. Confirming every
"open Spotify" would train you to say yes reflexively, which is worse than no
gate at all.
"""

from __future__ import annotations

import re
import time
from dataclasses import dataclass, field
from typing import Awaitable, Callable, Optional

from utils.logger import get_logger

logger = get_logger(__name__)

# How long a pending confirmation stays valid. Long enough to think, short
# enough that an unrelated "yes" minutes later cannot trigger it.
CONFIRM_TIMEOUT_SEC = 25.0

_YES = {
    "yes", "yeah", "yep", "yup", "sure", "ok", "okay", "confirm", "confirmed",
    "do it", "go ahead", "go for it", "affirmative", "correct", "right",
    "yes please", "please do", "proceed", "continue", "definitely",
}

_NO = {
    "no", "nope", "nah", "cancel", "stop", "abort", "never mind", "nevermind",
    "forget it", "dont", "don't", "negative", "wait", "hold on", "no thanks",
    "no thank you", "leave it", "not now",
}


@dataclass
class PendingAction:
    """An action waiting for the user to approve it."""

    description: str                       # spoken back when asking
    run: Callable[[], Awaitable[str]]      # executed only on approval
    created_at: float = field(default_factory=time.monotonic)

    def expired(self, timeout: float = CONFIRM_TIMEOUT_SEC) -> bool:
        return (time.monotonic() - self.created_at) > timeout


def classify_reply(text: str) -> Optional[bool]:
    """True = approved, False = declined, None = neither.

    None matters as much as the other two: if the user says something
    unrelated while a confirmation is pending, that utterance should be
    handled as a normal command rather than silently swallowed — and it must
    NOT be read as consent.
    """
    cleaned = re.sub(r"[^\w\s']", "", text.lower()).strip()
    if not cleaned:
        return None

    if cleaned in _YES:
        return True
    if cleaned in _NO:
        return False

    # Short affirmations/denials with filler: "yeah go ahead", "no don't".
    # Capped at 4 words so a long sentence beginning with "yes" is treated as
    # a fresh command instead of blanket approval for a destructive action.
    words = cleaned.split()
    if len(words) <= 4:
        if words[0] in {"no", "nope", "nah", "cancel", "stop", "dont", "don't"}:
            return False
        if words[0] in {"yes", "yeah", "yep", "yup", "sure", "ok", "okay"}:
            # "yes but wait" / "yeah no" must not approve.
            if any(w in _NO or w in {"but", "wait", "actually"} for w in words[1:]):
                return False
            return True

    return None


class ConfirmationGate:
    """Holds at most one pending action."""

    def __init__(self, timeout: float = CONFIRM_TIMEOUT_SEC):
        self._pending: Optional[PendingAction] = None
        self._timeout = timeout

    @property
    def pending(self) -> Optional[PendingAction]:
        if self._pending is not None and self._pending.expired(self._timeout):
            logger.info("Pending confirmation expired — action discarded")
            self._pending = None
        return self._pending

    def arm(self, action: PendingAction) -> None:
        if self._pending is not None:
            logger.info("Replacing an earlier unconfirmed action")
        self._pending = action
        logger.info(f"Awaiting confirmation: {action.description}")

    def clear(self) -> None:
        self._pending = None

    def take(self) -> Optional[PendingAction]:
        """Return the pending action and clear it, so it can only run once."""
        action = self.pending
        self._pending = None
        return action
